      width: 100%;
      color: var(--danger-text);
      background: var(--danger);
      box-shadow: 0 16px 34px #450a0a;
    }

    .trigger:hover {
      background: #dc2626;
      transform: translateY(-1px);
    }

    .trigger:active,
    .button:active {
      transform: translateY(1px);
    }

    .dialog {
      width: min(calc(100% - 2rem), 31rem);
      padding: 0;
      color: var(--text);
      border: 1px solid var(--line);
      border-radius: 1.5rem;
      background: var(--surface);
      box-shadow: 0 34px 90px #000000;
    }

    .dialog::backdrop {
      background: #020617;
