<body>
  <a class="skip-link" href="#main">Skip to main content</a>
  <div id="root"></div>

  <script>
    const image = {
      title: "Aurora over Black Ridge",
      meta: "Added April 22, 2026 - 4.8 MB",
      alt: "Illustration of a dark mountain landscape under a glowing aurora sky"
    };

    const html = String.raw;

    function App() {
      return html`
        <div class="page-shell">
          ${Header()}
          <main id="main">
            <section class="hero" aria-labelledby="page-title">
              ${HeroText()}
              ${ImagePreviewCard({ image })}
            </section>
          </main>
          ${Footer()}
        </div>
        ${DeleteImageDialog({ imageTitle: image.title })}
      `;
    }

    function Header() {
      return html`
        <header class="site-header">
          <div class="brand" aria-label="Image Library">
            <span class="brand-mark" aria-hidden="true">IL</span>
            <span>Image Library</span>
          </div>
          <span>Preview mode</span>
        </header>
      `;
    }

    function HeroText() {
      return html`
        <div>
          <p class="eyebrow">Selected image</p>
          <h1 id="page-title">Image preview</h1>
          <p class="intro">
            Review image details before keeping it in your collection or removing it from your library.
          </p>
          <p id="delete-status" class="status" aria-live="polite"></p>
        </div>
      `;
    }

    function ImagePreviewCard({ image }) {
      return html`
        <article class="preview-card" aria-labelledby="image-title">
          <div class="image-frame" role="img" aria-label="${image.alt}">
            <svg class="mountain" viewBox="0 0 700 320" aria-hidden="true" focusable="false">
              <path fill="currentColor" d="M0 320V190l112-86 78 64 80-122 108 148 76-66 92 92 64-42 90 82v60H0Z"></path>
            </svg>
          </div>
          <div class="card-body">
            <h2 id="image-title" class="image-title">${image.title}</h2>
            <p class="image-meta">${image.meta}</p>
            <button class="trigger" type="button" aria-haspopup="dialog">
              Delete image
            </button>
          </div>
        </article>
      `;
    }

    function DeleteImageDialog({ imageTitle }) {
      return html`
        <dialog class="dialog" aria-labelledby="dialog-title" aria-describedby="dialog-description">
          <div class="dialog-panel">
            <div class="dialog-icon" aria-hidden="true">
              <svg width="24" height="24" viewBox="0 0 24 24" fill="none" focusable="false">
                <path d="M10 11v6M14 11v6M5 7h14M9 7V5h6v2M7 7l1 13h8l1-13" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"></path>
              </svg>
            </div>
            <h2 id="dialog-title" class="dialog-title">Delete this image?</h2>
            <p id="dialog-description" class="dialog-copy">
              This will remove "${imageTitle}" from your library. This action cannot be undone.
            </p>
            <div class="dialog-actions">
              <button class="button" type="button" data-dialog-close>Cancel</button>
              <button class="button button-danger" type="button" data-confirm-delete>
                Delete image
              </button>
            </div>
          </div>
        </dialog>
      `;
    }

    function Footer() {
      return html`
        <footer class="site-footer">
          <span>Private library</span>
          <span>1 image selected</span>
        </footer>
      `;
    }

    function wireDeleteDialog() {
      const trigger = document.querySelector(".trigger");
      const dialog = document.querySelector(".dialog");
      const closeButton = document.querySelector("[data-dialog-close]");
      const confirmButton = document.querySelector("[data-confirm-delete]");
      const status = document.querySelector("#delete-status");
      let lastFocusedElement = null;

      function openDialog() {
        lastFocusedElement = document.activeElement;
        dialog.showModal();
        closeButton.focus();
      }

      function closeDialog() {
        dialog.close();
      }

      trigger.addEventListener("click", openDialog);
      closeButton.addEventListener("click", closeDialog);

      confirmButton.addEventListener("click", () => {
        closeDialog();
        status.textContent = `${image.title} has been removed from your library.`;
      });

      dialog.addEventListener("click", (event) => {
        if (event.target === dialog) {
          closeDialog();
        }
      });

      dialog.addEventListener("close", () => {
        if (lastFocusedElement instanceof HTMLElement) {
          lastFocusedElement.focus();
        }
      });
    }

    document.querySelector("#root").innerHTML = App();
    wireDeleteDialog();
  </script>
</body>
</html>
